53	// assertFaultReadsPrefix confirms through an independent connection that the
54	// injected fault really serves exactly the wantSeqs prefix before the read
55	// fails, so the 503s above exercise a mid-scan failure, not an early one.
56	func assertFaultReadsPrefix(t *testing.T, path string, wantSeqs ...int64) {
57		t.Helper()
58		db, err := sql.Open("sqlite", path)
59		if err != nil {
60			t.Fatalf("open control connection: %v", err)
