550			wantAccount string // decoded text the ledger must store verbatim
551		}{
552			{"direct chinese", `"账号"`, "账号"},
553			{"escaped chinese", `"\u8d26\u53f7"`, "账号"},
554			{"direct supplementary plane", `"😀"`, "😀"},
555			{"escaped supplementary plane", `"\uD83D\uDE00"`, "😀"},
556			{"escaped supplementary plane lowercase", `"\ud83d\ude00"`, "😀"},
557			{"direct replacement char", `"�"`, "�"},
