571			}
572			// The hash is computed over the decoded text, so an escaped
573			// surrogate pair and the same character submitted directly
574			// produce identical hashes at identical chain positions.
575			seq := int64(i + 1)
576			want := wantHash(seq, tc.wantAccount, "o", "r", "ok", "2026-10-05T00:00:00Z", prevHash)
