247	// setInsertFailure installs (or removes) a trigger that fails every INSERT
248	// on the events table while SELECTs and Ping keep working. It is installed
249	// from a connection the service does not own, so the product code stays
250	// unchanged and reads remain available throughout.
251	func setInsertFailure(t *testing.T, path string, enabled bool) {
252		t.Helper()
253		statement := "DROP TRIGGER IF EXISTS events_block_insert"
254		if enabled {
255			statement = `CREATE TRIGGER events_block_insert
256				BEFORE INSERT ON events
257				BEGIN
258					SELECT RAISE(FAIL, 'controlled write failure injected by regression test');
259				END;`
260		}
261		db, err := sql.Open("sqlite", path)
262		if err != nil {
263			t.Fatalf("open control connection: %v", err)
264		}
265		defer db.Close()
266		if _, err := db.Exec(statement); err != nil {
267			t.Fatalf("toggle insert failure (%v): %v", enabled, err)
268		}
269	}
