16	// The combined pagination regression works against one fixed input table:
17	// 104 records match account "carol" inside the main window
18	// [combinedFrom, combinedTo), interleaved with 19 records that each break
19	// exactly one condition (account case, surrounding whitespace, or the time
20	// window). Expected pages are derived from this table and the published
21	// semantics — exact account text, from inclusive, to exclusive, ascending
22	// seq — never from a query response.
23	const (
24		combinedAccount = "carol"
25		combinedFrom    = "2026-10-05T00:00:00Z"
26		combinedTo      = "2026-10-06T00:00:00Z"
27	)
28	
29	// combinedSeed is one predefined append input; match records whether the
30	// seed satisfies the main query by the public semantics.
31	type combinedSeed struct {
32		account    string
33		occurredAt string
34		match      bool
35	}
36	
37	// combinedSeeds returns the fixed input table. Matching records carry
38	// distinct in-window instants permuted so that time order differs from
39	// append order; non-matching records are interleaved in clusters, closing
40	// with a non-matching tail run after the last match.
41	func combinedSeeds() []combinedSeed {
42		matches := make([]combinedSeed, 0, 104)
43		// 101 in-window instants on distinct minutes: i*17 is coprime with the
44		// 1439 minutes of the day, so the minutes are unique and shuffled.
45		for i := 0; i < 101; i++ {
46			minute := (i * 17) % 1439
47			matches = append(matches, combinedSeed{
48				account:    combinedAccount,
49				occurredAt: "2026-10-05T" + twoDigits(minute/60) + ":" + twoDigits(minute%60) + ":00Z",
50				match:      true,
51			})
52		}
53		// Special matching records: a fraction longer than nanoseconds, a
54		// trailing-zero fraction, and an offset spelling of an in-window instant.
55		matches = append(matches,
56			combinedSeed{combinedAccount, "2026-10-05T12:00:00.000000000000001Z", true},
57			combinedSeed{combinedAccount, "2026-10-05T06:00:00.2500Z", true},
58			combinedSeed{combinedAccount, "2026-10-05T09:30:00+08:00", true},
59		)
60		nonMatches := []combinedSeed{
61			{"Carol", "2026-10-05T10:00:00Z", false},
62			{"CAROL", "2026-10-05T11:00:00Z", false},
63			{" carol", "2026-10-05T12:30:00Z", false},
64			{"carol ", "2026-10-05T13:30:00Z", false},
65			{"  carol  ", "2026-10-05T14:30:00Z", false},
66			{combinedAccount, "2026-10-06T00:00:00Z", false},                // exactly at to: excluded
67			{combinedAccount, "2026-10-04T23:59:59.999999999999999Z", false}, // just before from
68			{combinedAccount, "2026-10-06T00:00:00.000000000000001Z", false}, // just after to
69			{combinedAccount, "2026-10-04T12:00:00Z", false},
70			{combinedAccount, "2026-10-06T12:00:00Z", false},
71			{"dave", "2026-10-05T08:00:00Z", false},
72			{"dave", "2026-10-05T09:00:00Z", false},
73			{"dave", "2026-10-05T15:00:00Z", false},
74			{"dave", "2026-10-05T16:00:00Z", false},
75			{"eve", "2026-10-05T17:00:00Z", false},
76			{"CAROL ", "2026-10-05T18:00:00Z", false},
77			{"dave", "2026-10-04T10:00:00Z", false},
78			{"eve", "2026-10-06T10:00:00Z", false},
79			{"Carol", "2026-10-05T19:00:00Z", false},
80		}
81		// Interleave matching chunks with non-matching clusters (one cluster of
82		// six in the middle) and end with a non-matching tail run of four.
83		pattern := [][2]int{{5, 2}, {10, 1}, {7, 6}, {20, 1}, {15, 2}, {30, 3}, {17, 4}}
84		var seeds []combinedSeed
85		mi, ni := 0, 0
86		for _, chunk := range pattern {
87			for k := 0; k < chunk[0]; k++ {
88				seeds = append(seeds, matches[mi])
89				mi++
90			}
91			for k := 0; k < chunk[1]; k++ {
92				seeds = append(seeds, nonMatches[ni])
93				ni++
94			}
95		}
96		return seeds
97	}
98	
99	func twoDigits(n int) string {
100		return string(rune('0'+n/10)) + string(rune('0'+n%10))
101	}
102	
103	// combinedWindowQuery builds the encoded query for account "carol" over the
104	// given window; limit 0 omits the parameter to exercise the default.
105	func combinedWindowQuery(from, to string, limit int64) string {
106		values := url.Values{}
107		values.Set("account", combinedAccount)
108		values.Set("from", from)
109		values.Set("to", to)
110		if limit > 0 {
111			values.Set("limit", strconv.FormatInt(limit, 10))
112		}
113		return values.Encode()
114	}
115	
116	// filterWindow applies the public window semantics (from inclusive, to
117	// exclusive) to the predefined posts. from and to must be normalized UTC.
118	func filterWindow(posts []map[string]any, from, to string) []map[string]any {
119		var out []map[string]any
120		for _, post := range posts {
121			at := post["occurred_at"].(string)
122			if store.CompareInstants(at, from) >= 0 && store.CompareInstants(at, to) < 0 {
123				out = append(out, post)
124			}
125		}
126		return out
127	}
128	
129	// checkCombinedFixture guards the input table itself: the match flags agree
130	// with the public semantics applied to the stored (normalized) text, and the
131	// occurred_at order genuinely differs from the append order.
132	func checkCombinedFixture(t *testing.T, seeds []combinedSeed, posts []map[string]any) {
133		t.Helper()
134		if len(seeds) != 123 {
135			t.Fatalf("fixture: %d seeds, want 123", len(seeds))
136		}
137		descent := false
138		for i, seed := range seeds {
139			at := posts[i]["occurred_at"].(string)
140			match := seed.account == combinedAccount &&
141				store.CompareInstants(at, combinedFrom) >= 0 &&
142				store.CompareInstants(at, combinedTo) < 0
143			if match != seed.match {
144				t.Fatalf("fixture: seed %d (%q, %q) match = %v, semantics give %v",
145					i, seed.account, seed.occurredAt, seed.match, match)
146			}
147			if i > 0 && store.CompareInstants(at, posts[i-1]["occurred_at"].(string)) < 0 {
148				descent = true
149			}
150		}
151		if !descent {
152			t.Fatal("fixture: occurred_at order must differ from append order")
153		}
154	}
155	
156	// wantCombinedTraversal pages through GET /events for the given window until
157	// the cursor closes, checking every page against the expected append
158	// responses: page sizes, full record fields, ascending seq, the filter
159	// conditions on every record, and a cursor that points at the page's last
160	// record until no further matches exist. limit 0 exercises the default page
161	// size; afterSeq seeds the first page's cursor.
162	func wantCombinedTraversal(t *testing.T, router http.Handler, from, to string, limit int64, afterSeq string, expected []map[string]any) {
163		t.Helper()
164		normFrom, ok := normalizeOccurredAt(from)
165		if !ok {
166			t.Fatalf("bad from %q", from)
167		}
168		normTo, ok := normalizeOccurredAt(to)
169		if !ok {
170			t.Fatalf("bad to %q", to)
171		}
172		effective := limit
173		if effective == 0 {
174			effective = defaultEventPageLimit
175		}
176	
177		query := combinedWindowQuery(from, to, limit)
178		if afterSeq != "" {
179			query += "&after_seq=" + afterSeq
180		}
181	
182		seen := 0
183		var prevSeq float64
184		for {
185			recorder := getEventsQuery(t, router, query)
186			if recorder.Code != http.StatusOK {
187				t.Fatalf("query %q: status = %d (%s)", query, recorder.Code, recorder.Body.String())
188			}
189			events, next := decodePage(t, recorder)
190	
191			wantLen := int(effective)
192			if remaining := len(expected) - seen; remaining < wantLen {
193				wantLen = remaining
194			}
195			if len(events) != wantLen {
196				t.Fatalf("query %q: page has %d events, want %d", query, len(events), wantLen)
197			}
198			for _, event := range events {
199				posted := expected[seen]
200				if len(event) != 8 {
201					t.Fatalf("event keys = %v, want the 8 append response fields", event)
202				}
203				for _, key := range []string{"account", "operation", "resource", "result", "occurred_at", "seq", "prev_hash", "hash"} {
204					if event[key] != posted[key] {
205						t.Fatalf("event %s = %v, want the appended %v", key, event[key], posted[key])
206					}
207				}
208				// Every returned record satisfies all filter conditions at once.
209				if event["account"] != combinedAccount {
210					t.Fatalf("event account = %v, want %q", event["account"], combinedAccount)
211				}
212				at := event["occurred_at"].(string)
213				if store.CompareInstants(at, normFrom) < 0 || store.CompareInstants(at, normTo) >= 0 {
214					t.Fatalf("event occurred_at %q outside [%q, %q)", at, normFrom, normTo)
215				}
216				seq := event["seq"].(float64)
217				if seen > 0 && seq <= prevSeq {
218					t.Fatalf("seq %v does not follow %v", seq, prevSeq)
219				}
220				prevSeq = seq
221				seen++
222			}
223	
224			if seen == len(expected) {
225				// No further matches: the cursor closes even when non-matching
226				// records still follow in the ledger.
227				if next != nil {
228					t.Fatalf("next_after_seq = %v after the last match, want null", next)
229				}
230				return
231			}
232			// More matches exist: the cursor points at this page's last record,
233			// however many non-matching records lie before the next match.
234			last := events[len(events)-1]["seq"]
235			if next != last {
236				t.Fatalf("next_after_seq = %v, want the page's last seq %v", next, last)
237			}
238			query = combinedWindowQuery(from, to, limit) + "&after_seq=" + strconv.FormatInt(int64(last.(float64)), 10)
239		}
240	}
241	
242	// wantErrorShape asserts the published error contract: the body is only a
243	// top-level error object with string code and message, and leaks nothing
244	// else — no partial page, SQL, stack trace or filesystem path.
245	func wantErrorShape(t *testing.T, recorder *httptest.ResponseRecorder, status int, code string) {
246		t.Helper()
247		if recorder.Code != status {
248			t.Fatalf("status = %d, want %d (%s)", recorder.Code, status, recorder.Body.String())
249		}
250		var decoded map[string]any
251		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
252			t.Fatalf("decode error body: %v", err)
253		}
254		if len(decoded) != 1 {
255			t.Fatalf("error body keys = %v, want only the top-level error object", decoded)
256		}
257		errObj, ok := decoded["error"].(map[string]any)
258		if !ok || len(errObj) != 2 {
259			t.Fatalf("error = %v, want an object with only code and message", decoded["error"])
260		}
261		if errObj["code"] != code {
262			t.Fatalf("code = %v, want %q", errObj["code"], code)
263		}
264		if message, ok := errObj["message"].(string); !ok || message == "" {
265			t.Fatalf("message = %v, want a non-empty string", errObj["message"])
266		}
267		for _, leak := range []string{`"events"`, "next_after_seq", "SELECT", "goroutine", ".db"} {
268			if strings.Contains(recorder.Body.String(), leak) {
269				t.Fatalf("error body leaks %q: %s", leak, recorder.Body.String())
270			}
271		}
272	}
273	
274	func TestGetEventsCombinedPaginationRegression(t *testing.T) {
275		router := NewRouter(openTestStore(t))
276	
277		// Build the ledger through POST /events and keep every append response;
278		// the expected pages below are derived from these predefined inputs.
279		seeds := combinedSeeds()
280		posts := make([]map[string]any, 0, len(seeds))
281		for _, seed := range seeds {
282			posts = append(posts, mustPost(t, router, eventBody(seed.account, seed.occurredAt)))
283		}
284		for i, post := range posts {
285			if post["seq"] != float64(i+1) {
286				t.Fatalf("append %d seq = %v, want %d", i, post["seq"], i+1)
287			}
288		}
289		checkCombinedFixture(t, seeds, posts)
290	
291		var expected []map[string]any
292		var carolPosts []map[string]any
293		for i, seed := range seeds {
294			if seed.account == combinedAccount {
295				carolPosts = append(carolPosts, posts[i])
296			}
297			if seed.match {
298				expected = append(expected, posts[i])
299			}
300		}
301		if len(expected) != 104 {
302			t.Fatalf("fixture: %d matching records, want 104", len(expected))
303		}
304	
305		// Page sizes 1, the default 50 and the maximum 100 over 104 matches:
306		// 104 pages, three pages (50, 50, 4) and two pages (100, 4).
307		wantCombinedTraversal(t, router, combinedFrom, combinedTo, 1, "", expected)
308		wantCombinedTraversal(t, router, combinedFrom, combinedTo, 0, "", expected)
309		wantCombinedTraversal(t, router, combinedFrom, combinedTo, 100, "", expected)
310	
311		// Bounds spelled with a timezone offset name the same window and must
312		// produce the same pages as the UTC spelling.
313		wantCombinedTraversal(t, router, "2026-10-05T08:00:00+08:00", "2026-10-06T08:00:00+08:00", 100, "", expected)
314	
315		// Sub-windows sized by the sorted matching instants: exactly one full
316		// default page closes the cursor, and a short page stays short.
317		instants := make([]string, len(expected))
318		for i, post := range expected {
319			instants[i] = post["occurred_at"].(string)
320		}
321		sort.Slice(instants, func(a, b int) bool { return store.CompareInstants(instants[a], instants[b]) < 0 })
322		for i := 1; i < len(instants); i++ {
323			if store.CompareInstants(instants[i-1], instants[i]) == 0 {
324				t.Fatalf("fixture: duplicate matching instant %q", instants[i])
325			}
326		}
327		fullPage := filterWindow(expected, instants[0], instants[50])
328		if len(fullPage) != 50 {
329			t.Fatalf("fixture: sub-window has %d matches, want exactly one default page", len(fullPage))
330		}
331		wantCombinedTraversal(t, router, instants[0], instants[50], 0, "", fullPage)
332		shortPage := filterWindow(expected, instants[0], instants[3])
333		if len(shortPage) != 3 {
334			t.Fatalf("fixture: sub-window has %d matches, want 3", len(shortPage))
335		}
336		wantCombinedTraversal(t, router, instants[0], instants[3], 0, "", shortPage)
337	
338		// A trailing-zero fraction names the same instant: the inclusive lower
339		// bound keeps the record, the exclusive upper bound drops it, and the
340		// stored fraction text keeps all four digits.
341		zeroPost := filterWindow(expected, "2026-10-05T06:00:00.25Z", "2026-10-05T06:00:01Z")
342		if len(zeroPost) != 1 {
343			t.Fatalf("fixture: %d records at the trailing-zero instant, want 1", len(zeroPost))
344		}
345		wantCombinedTraversal(t, router, "2026-10-05T06:00:00.25Z", "2026-10-05T06:00:01Z", 0, "", zeroPost)
346		if zeroPost[0]["occurred_at"] != "2026-10-05T06:00:00.2500Z" {
347			t.Fatalf("stored fraction = %v, want the original .2500 text", zeroPost[0]["occurred_at"])
348		}
349		events, next := decodePage(t, getEventsQuery(t, router,
350			combinedWindowQuery("2026-10-05T06:00:00Z", "2026-10-05T06:00:00.25Z", 0)))
351		if len(events) != 0 || next != nil {
352			t.Fatalf("events = %v next = %v, want the equal upper bound to exclude the record", events, next)
353		}
354	
355		// A fraction longer than nanoseconds is stored verbatim and still
356		// ordered exactly: the record sits inside its second, and an upper
357		// bound equal to its own instant excludes it.
358		fracPost := filterWindow(expected, "2026-10-05T12:00:00Z", "2026-10-05T12:00:01Z")
359		if len(fracPost) != 1 {
360			t.Fatalf("fixture: %d records in the fraction second, want 1", len(fracPost))
361		}
362		wantCombinedTraversal(t, router, "2026-10-05T12:00:00.000000000000001Z", "2026-10-05T12:00:01Z", 0, "", fracPost)
363		if fracPost[0]["occurred_at"] != "2026-10-05T12:00:00.000000000000001Z" {
364			t.Fatalf("stored fraction = %v, want the original 15-digit text", fracPost[0]["occurred_at"])
365		}
366		events, next = decodePage(t, getEventsQuery(t, router,
367			combinedWindowQuery("2026-10-05T12:00:00Z", "2026-10-05T12:00:00.000000000000001Z", 0)))
368		if len(events) != 0 || next != nil {
369			t.Fatalf("events = %v next = %v, want the equal upper bound to exclude the record", events, next)
370		}
371	
372		// The record exactly at the main window's to is excluded there, but a
373		// window starting at that same instant includes it: from is inclusive.
374		dayAfter := filterWindow(carolPosts, combinedTo, "2026-10-07T00:00:00Z")
375		if len(dayAfter) != 3 {
376			t.Fatalf("fixture: %d records on the next day, want 3", len(dayAfter))
377		}
378		wantCombinedTraversal(t, router, combinedTo, "2026-10-07T00:00:00Z", 0, "", dayAfter)
379	
380		// No matching account, no matching instant, and a cursor past the tail
381		// all return an empty page and a null cursor.
382		aliceQuery := url.Values{}
383		aliceQuery.Set("account", "alice")
384		aliceQuery.Set("from", combinedFrom)
385		aliceQuery.Set("to", combinedTo)
386		events, next = decodePage(t, getEventsQuery(t, router, aliceQuery.Encode()))
387		if len(events) != 0 || next != nil {
388			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
389		}
390		events, next = decodePage(t, getEventsQuery(t, router,
391			combinedWindowQuery("2026-10-07T00:00:00Z", "2026-10-08T00:00:00Z", 0)))
392		if len(events) != 0 || next != nil {
393			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
394		}
395		events, next = decodePage(t, getEventsQuery(t, router,
396			combinedWindowQuery(combinedFrom, combinedTo, 0)+"&after_seq="+strconv.Itoa(len(seeds))))
397		if len(events) != 0 || next != nil {
398			t.Fatalf("events = %v next = %v, want empty page and null cursor past the tail", events, next)
399		}
400	
401		// A matching record appended between two page reads is visible to later
402		// pages, while re-reading the already full first page yields identical
403		// content.
404		firstRecorder := getEventsQuery(t, router, combinedWindowQuery(combinedFrom, combinedTo, 0))
405		firstEvents, firstNext := decodePage(t, firstRecorder)
406		if len(firstEvents) != 50 || firstNext != expected[49]["seq"] {
407			t.Fatalf("first page = %d events, cursor = %v; want 50 events ending at seq %v",
408				len(firstEvents), firstNext, expected[49]["seq"])
409		}
410		extra := mustPost(t, router, eventBody(combinedAccount, "2026-10-05T20:00:00Z"))
411		again := getEventsQuery(t, router, combinedWindowQuery(combinedFrom, combinedTo, 0))
412		if again.Body.String() != firstRecorder.Body.String() {
413			t.Fatalf("first page changed after an append:\n%s\n%s", firstRecorder.Body.String(), again.Body.String())
414		}
415		remainder := append(append([]map[string]any{}, expected[50:]...), extra)
416		wantCombinedTraversal(t, router, combinedFrom, combinedTo, 0,
417			strconv.FormatInt(int64(firstNext.(float64)), 10), remainder)
418	
419		// The reads never touched the chain: the whole ledger still verifies.
420		total := len(seeds) + 1
421		verifyRecorder := httptest.NewRecorder()
422		router.ServeHTTP(verifyRecorder, httptest.NewRequest(http.MethodGet, "/ledger/verify", nil))
423		if verifyRecorder.Code != http.StatusOK {
424			t.Fatalf("verify: status = %d (%s)", verifyRecorder.Code, verifyRecorder.Body.String())
425		}
426		result := decodeEvent(t, verifyRecorder)
427		if result["valid"] != true || result["checked"] != float64(total) || result["first_invalid_seq"] != nil {
428			t.Fatalf("verify = %v, want a valid chain of %d records", result, total)
429		}
430	
431		// Appends still continue at the tail, chained to the previous record.
432		tail := mustPost(t, router, eventBody(combinedAccount, "2026-10-05T21:00:00Z"))
433		if tail["seq"] != float64(total+1) || tail["prev_hash"] != extra["hash"] {
434			t.Fatalf("tail append = %v, want seq %d chained to %v", tail, total+1, extra["hash"])
435		}
436		verifyRecorder = httptest.NewRecorder()
437		router.ServeHTTP(verifyRecorder, httptest.NewRequest(http.MethodGet, "/ledger/verify", nil))
438		result = decodeEvent(t, verifyRecorder)
439		if result["valid"] != true || result["checked"] != float64(total+1) {
440			t.Fatalf("verify = %v, want a valid chain of %d records", result, total+1)
441		}
442	}
443	
444	func TestGetEventsCombinedOnEmptyLedger(t *testing.T) {
445		router := NewRouter(openTestStore(t))
446	
447		// Every parameter combined against an empty ledger: an empty array and
448		// a null cursor, not an error.
449		recorder := getEventsQuery(t, router, combinedWindowQuery(combinedFrom, combinedTo, 100)+"&after_seq=41")
450		if recorder.Code != http.StatusOK {
451			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
452		}
453		if !strings.Contains(recorder.Body.String(), `"events":[]`) {
454			t.Fatalf("body = %s, want an empty events array", recorder.Body.String())
455		}
456		events, next := decodePage(t, recorder)
457		if len(events) != 0 || next != nil {
458			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
459		}
460	}
461	
462	func TestGetEventsCombinedRejectsInvalidInput(t *testing.T) {
463		router := NewRouter(openTestStore(t))
464		cases := []string{
465			"account=carol&account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z", // repeated parameter
466			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=1&limit=1",
467			"account=carol&from=2026-10-06T00:00:00Z&to=2026-10-05T00:00:00Z",                // from after to
468			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-05T00:00:00Z",                // empty window
469			"account=carol&from=2026-10-05T08:00:00%2B08:00&to=2026-10-05T00:00:00Z",         // same instant
470			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=0",        // below range
471			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=101",      // above range
472			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&after_seq=-1",
473			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&after_seq=9223372036854775808",
474		}
475		for _, query := range cases {
476			wantErrorShape(t, getEventsQuery(t, router, query), http.StatusBadRequest, "invalid_audit_input")
477		}
478	}
479	
480	func TestGetEventsCombinedStorageUnavailable(t *testing.T) {
481		st := openTestStore(t)
482		router := NewRouter(st)
483		st.Close()
484	
485		// Even with storage down, invalid parameters are rejected as 400 first.
486		wantErrorShape(t, getEventsQuery(t, router,
487			"account=carol&account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z"),
488			http.StatusBadRequest, "invalid_audit_input")
489		wantErrorShape(t, getEventsQuery(t, router,
490			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=101"),
491			http.StatusBadRequest, "invalid_audit_input")
492	
493		// A fully valid combined request surfaces the storage failure as 503.
494		wantErrorShape(t, getEventsQuery(t, router,
495			combinedWindowQuery(combinedFrom, combinedTo, 100)+"&after_seq=10"),
496			http.StatusServiceUnavailable, "storage_unavailable")
497	}
