			return invalid()
		}
	}

	var ok bool
	if input.Account, ok = requiredString(raw, "account"); !ok || strings.TrimSpace(input.Account) == "" {
		return invalid()
	}
	if input.Operation, ok = requiredString(raw, "operation"); !ok || strings.TrimSpace(input.Operation) == "" {
		return invalid()
	}
	if input.Resource, ok = requiredString(raw, "resource"); !ok || strings.TrimSpace(input.Resource) == "" {
		return invalid()
	}
	if input.Result, ok = requiredString(raw, "result"); !ok || strings.TrimSpace(input.Result) == "" {
		return invalid()
	}
	occurredAt, ok := requiredString(raw, "occurred_at")
	if !ok {
		return invalid()
	}
	if input.OccurredAt, ok = normalizeOccurredAt(occurredAt); !ok {
		return invalid()
	}

	if rawSeq, present := raw["seq"]; present {
		literal := string(rawSeq)
		if !isUintLiteral(literal) {
			return invalid()
		}
		seq, err := strconv.ParseInt(literal, 10, 64)
		if err != nil || seq <= 0 {
			return invalid()
		}
		input.Seq = &seq
	}
	return input, true
}

// hasUnpairedSurrogateEscape scans the raw JSON document for \uXXXX escapes
// inside string literals and reports whether any of them encodes a surrogate
// that is not one half of an adjacent, correctly ordered pair. A high
// surrogate must be followed immediately by a low-surrogate escape inside the
// same string; a low surrogate on its own (or a reversed pair) is rejected.
// Escaped backslashes are consumed first, so text like "\\uD83D" is read as
// plain characters, not as a Unicode escape. Anything the scan cannot parse
// is left for the JSON decoder to reject.
func hasUnpairedSurrogateEscape(body []byte) bool {
	inString := false
	for i := 0; i < len(body); i++ {
		c := body[i]
		if !inString {
			if c == '"' {
				inString = true
			}
			continue
		}
		switch c {
		case '"':
			inString = false
		case '\\':
			if i+1 >= len(body) || body[i+1] != 'u' {
				// Any other escape (including \\) consumes one byte.
				i++
				continue
			}
			if i+6 > len(body) {
				return false // truncated escape: malformed JSON
			}
			v, ok := parseHex4(body[i+2 : i+6])
