			Hash:       event.Hash,
		})
	}
}

// parseEventInput validates the request body against the audit contract. On
// any violation it writes the invalid_audit_input error and reports false.
func parseEventInput(c *gin.Context) (store.EventInput, bool) {
	var input store.EventInput
	invalid := func() (store.EventInput, bool) {
		writeError(c, http.StatusBadRequest, "invalid_audit_input", "request body is not a valid audit event")
		return store.EventInput{}, false
	}

	body, err := io.ReadAll(io.LimitReader(c.Request.Body, maxEventBodyBytes+1))
	if err != nil || len(body) > maxEventBodyBytes {
		return invalid()
	}

	// The JSON decoder silently rewrites invalid UTF-8 bytes and unpaired
	// surrogate escapes to U+FFFD; the ledger must only store text that
	// decodes losslessly, so reject both before decoding.
	if !utf8.Valid(body) || hasUnpairedSurrogateEscape(body) {
		return invalid()
	}

	var raw map[string]json.RawMessage
	decoder := json.NewDecoder(bytes.NewReader(body))
	if err := decoder.Decode(&raw); err != nil || raw == nil {
		return invalid()
	}
	var extra struct{}
	if err := decoder.Decode(&extra); err != io.EOF {
		return invalid()
	}

	for key := range raw {
		switch key {
		case "account", "operation", "resource", "result", "occurred_at", "seq":
		default:
			// hash, prev_hash and any unknown field are forbidden.
			return invalid()
		}
	}

	var ok bool
	if input.Account, ok = requiredString(raw, "account"); !ok || strings.TrimSpace(input.Account) == "" {
		return invalid()
	}
	if input.Operation, ok = requiredString(raw, "operation"); !ok || strings.TrimSpace(input.Operation) == "" {
		return invalid()
	}
	if input.Resource, ok = requiredString(raw, "resource"); !ok || strings.TrimSpace(input.Resource) == "" {
		return invalid()
	}
	if input.Result, ok = requiredString(raw, "result"); !ok || strings.TrimSpace(input.Result) == "" {
		return invalid()
	}
	occurredAt, ok := requiredString(raw, "occurred_at")
	if !ok {
		return invalid()
	}
	if input.OccurredAt, ok = normalizeOccurredAt(occurredAt); !ok {
		return invalid()
	}

	if rawSeq, present := raw["seq"]; present {
		literal := string(rawSeq)
		if !isUintLiteral(literal) {
			return invalid()
		}
		seq, err := strconv.ParseInt(literal, 10, 64)
		if err != nil || seq <= 0 {
			return invalid()
		}
		input.Seq = &seq
	}
	return input, true
}

// hasUnpairedSurrogateEscape scans the raw JSON document for \uXXXX escapes
// inside string literals and reports whether any of them encodes a surrogate
// that is not one half of an adjacent, correctly ordered pair. A high
// surrogate must be followed immediately by a low-surrogate escape inside the
// same string; a low surrogate on its own (or a reversed pair) is rejected.
// Escaped backslashes are consumed first, so text like "\\uD83D" is read as
// plain characters, not as a Unicode escape. Anything the scan cannot parse
// is left for the JSON decoder to reject.
func hasUnpairedSurrogateEscape(body []byte) bool {
	inString := false
	for i := 0; i < len(body); i++ {
		c := body[i]
		if !inString {
			if c == '"' {
				inString = true
			}
			continue
		}
		switch c {
		case '"':
			inString = false
		case '\\':
			if i+1 >= len(body) || body[i+1] != 'u' {
				// Any other escape (including \\) consumes one byte.
				i++
				continue
			}
			if i+6 > len(body) {
				return false // truncated escape: malformed JSON
			}
			v, ok := parseHex4(body[i+2 : i+6])
			if !ok {
				return false // not hex: the decoder rejects it
			}
			switch {
			case v >= 0xD800 && v <= 0xDBFF:
				// A high surrogate is only valid as the first half of a
				// pair immediately followed by a low-surrogate escape.
				if i+12 <= len(body) && body[i+6] == '\\' && body[i+7] == 'u' {
					if low, ok := parseHex4(body[i+8 : i+12]); ok && low >= 0xDC00 && low <= 0xDFFF {
						i += 11
						continue
					}
				}
				return true
			case v >= 0xDC00 && v <= 0xDFFF:
				// A low surrogate without a preceding high surrogate.
				return true
			}
			i += 5
		}
	}
	return false
}

// parseHex4 reads exactly four hexadecimal digits, either case.
func parseHex4(b []byte) (int, bool) {
	v := 0
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v += int(c - '0')
		case c >= 'a' && c <= 'f':
			v += int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v += int(c-'A') + 10
		default:
			return 0, false
		}
	}
	return v, true
}

// requiredString extracts a string field that must be present, non-null and
// actually a JSON string.
func requiredString(raw map[string]json.RawMessage, name string) (string, bool) {
	value, present := raw[name]
	if !present || string(value) == "null" {
		return "", false
	}
	var s string
	if err := json.Unmarshal(value, &s); err != nil {
		return "", false
	}
	return s, true
}

// isUintLiteral reports whether the raw JSON value is a non-negative integer
// literal with no fraction, exponent or sign.
func isUintLiteral(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// normalizeOccurredAt parses a strict RFC3339 timestamp with an explicit
// timezone, rejects leap seconds, and returns the UTC form keeping the
// fractional-second digits exactly as supplied.
func normalizeOccurredAt(value string) (string, bool) {
	const headLen = len("2006-01-02T15:04:05")
	if len(value) < headLen+1 {
		return "", false
	}
	head := value[:headLen]
	if head[4] != '-' || head[7] != '-' || head[10] != 'T' || head[13] != ':' || head[16] != ':' {
		return "", false
	}
	field := func(start, width int) (int, bool) {
		v := 0
		for i := start; i < start+width; i++ {
			if head[i] < '0' || head[i] > '9' {
				return 0, false
			}
			v = v*10 + int(head[i]-'0')
		}
		return v, true
	}
	year, ok1 := field(0, 4)
	month, ok2 := field(5, 2)
	day, ok3 := field(8, 2)
	hour, ok4 := field(11, 2)
	minute, ok5 := field(14, 2)
	second, ok6 := field(17, 2)
	if !ok1 || !ok2 || !ok3 || !ok4 || !ok5 || !ok6 {
		return "", false
	}
	if second > 59 {
		// Leap seconds are not accepted.
		return "", false
	}

	rest := value[headLen:]
	fraction := ""
	if strings.HasPrefix(rest, ".") {
		i := 1
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		if i == 1 {
			return "", false
		}
		fraction = rest[:i]
		rest = rest[i:]
	}

	offsetMinutes := 0
	switch {
	case rest == "Z":
	case len(rest) == 6 && (rest[0] == '+' || rest[0] == '-') && rest[3] == ':' &&
		isDigit(rest[1]) && isDigit(rest[2]) && isDigit(rest[4]) && isDigit(rest[5]):
		oh := int(rest[1]-'0')*10 + int(rest[2]-'0')
		om := int(rest[4]-'0')*10 + int(rest[5]-'0')
		if oh > 23 || om > 59 {
			return "", false
		}
		offsetMinutes = oh*60 + om
		if rest[0] == '-' {
			offsetMinutes = -offsetMinutes
		}
	default:
		return "", false
	}

	t := time.Date(year, time.Month(month), day, hour, minute, second, 0, time.UTC)
	if t.Year() != year || int(t.Month()) != month || t.Day() != day || t.Hour() != hour || t.Minute() != minute {
		return "", false
	}
	utc := t.Add(time.Duration(-offsetMinutes) * time.Minute)
	if utc.Year() < 0 || utc.Year() > 9999 {
		// The UTC form must stay a four-digit RFC3339 year.
		return "", false
	}
	return utc.Format("2006-01-02T15:04:05") + fraction + "Z", true
}

func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func writeError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

